import java.util.List;
import java.util.Locale;

public class SolutionTest {
    public static void main(String[] args) {
        Solution.clear();
        expect(IllegalArgumentException.class, () -> Solution.send(null, "bob"));
        expect(IllegalArgumentException.class, () -> Solution.send("alice", "  "));
        expect(IllegalArgumentException.class, () -> Solution.receivedBy(null));
        expect(IllegalArgumentException.class, () -> Solution.connected("alice", ""));
        expect(IllegalArgumentException.class, () -> Solution.decide(" ", "bob", Solution.Decision.ACCEPTED));

        check(!Solution.send(" Alice ", "alice"), "normalized self-invitation rejected");
        check(!Solution.connected("same", " SAME "), "self is never connected");

        check(Solution.send("Charlie", " Bob "), "first invitation");
        check(Solution.send("alice", "bob"), "second invitation");
        check(!Solution.send(" ALICE ", " BOB "), "duplicate invitation rejected");
        check(!Solution.send("bob", "ALICE"), "reverse invitation rejected");

        List<Solution.Invite> received1 = Solution.receivedBy(" BOB ");
        List<Solution.Invite> received2 = Solution.receivedBy("bob");
        check(received1.equals(List.of(
                new Solution.Invite("alice", "bob"),
                new Solution.Invite("charlie", "bob"))), "received invitations sorted and normalized");
        check(received1 != received2, "received lists newly allocated");
        expect(UnsupportedOperationException.class, () -> received1.clear());

        check(Solution.decide("ALICE", "Bob", Solution.Decision.DECLINED), "decline existing invitation");
        check(!Solution.decide("alice", "bob", Solution.Decision.ACCEPTED), "removed invitation cannot be decided twice");
        check(!Solution.connected("alice", "bob"), "decline does not connect");

        check(Solution.decide(" charlie ", "BOB", Solution.Decision.ACCEPTED), "accept invitation");
        check(Solution.connected("charlie", "bob"), "forward connection");
        check(Solution.connected(" BOB ", " CHARLIE "), "symmetric connection");
        check(!Solution.send("bob", "charlie"), "connected users cannot invite");
        check(Solution.receivedBy("bob").isEmpty(), "decided invitations removed");

        Locale previous = Locale.getDefault();
        try {
            Locale.setDefault(new Locale("tr", "TR"));
            Solution.clear();
            check(Solution.send(" I ", "USER"), "send under Turkish default locale");
            check(Solution.receivedBy("user").equals(List.of(new Solution.Invite("i", "user"))), "Locale.ROOT normalization");
        } finally {
            Locale.setDefault(previous);
        }

        Solution.clear();
        Solution.clear();
        check(Solution.receivedBy("nobody").isEmpty(), "clear is idempotent");
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expect(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw new AssertionError("expected " + type.getName() + " but got " + error, error);
        }
        throw new AssertionError("expected " + type.getName());
    }
}

